import { useEffect, useRef } from 'react'
import { copy } from '../copy'

interface ConfirmDialogProps {
  open: boolean
  onCancel: () => void
  onConfirm: () => void
}

// Spec §8.3 (D-20, D-30): native modal <dialog>, no JS focus trap. Focus is set in code:
// Cancel when it opens; the parent moves focus after it closes.
export function ConfirmDialog({ open, onCancel, onConfirm }: ConfirmDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return
    if (open && !dialog.open) {
      dialog.showModal()
      cancelRef.current?.focus()
    } else if (!open && dialog.open) {
      dialog.close()
    }
  }, [open])

  return (
    <dialog
      ref={dialogRef}
      className="confirm-dialog"
      aria-labelledby="clear-dialog-text"
      aria-describedby="clear-dialog-hint"
      onCancel={(event) => {
        // Escape: close through state, so focus handling stays in one place.
        event.preventDefault()
        onCancel()
      }}
    >
      <p id="clear-dialog-text" className="dialog-text">
        {copy.dialog.clearText}
      </p>
      <p id="clear-dialog-hint" className="hint">
        {copy.dialog.clearHint}
      </p>
      <div className="actions">
        <button type="button" ref={cancelRef} className="secondary" onClick={onCancel}>
          {copy.dialog.cancel}
        </button>
        <button type="button" className="primary" onClick={onConfirm}>
          {copy.dialog.confirm}
        </button>
      </div>
    </dialog>
  )
}
import { useRef, type FormEvent, type RefObject } from 'react'
import { calculateLoan } from '../../domain/loan'
import type { ErrorCode, Field, Unit } from '../../domain/types'
import { validateInputs } from '../../domain/validate'
import { createEntry, saveEntry } from '../../storage/history'
import { useApp } from '../AppContext'
import { copy } from '../copy'
import { CurrencySelect } from './CurrencySelect'

const FIELD_ORDER: Field[] = ['amount', 'rate', 'tenure']
const UNITS: Unit[] = ['years', 'months']

interface TextFieldProps {
  id: Field
  label: string
  value: string
  error: ErrorCode | undefined
  inputMode: 'decimal' | 'numeric'
  inputRef: RefObject<HTMLInputElement | null>
  onChange: (value: string) => void
}

function TextField({ id, label, value, error, inputMode, inputRef, onChange }: TextFieldProps) {
  const errorId = `${id}-error`
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input
        ref={inputRef}
        id={id}
        type="text"
        inputMode={inputMode}
        autoComplete="off"
        value={value}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        onChange={(e) => onChange(e.target.value)}
      />
      {/* Spec §8.3: errors sit under their field, in a polite live region. */}
      <p id={errorId} className="field-error" aria-live="polite">
        {error ? copy.err[error] : ''}
      </p>
    </div>
  )
}

export function LoanForm() {
  const { state, dispatch } = useApp()
  const { inputs, errors, settings } = state
  const amountRef = useRef<HTMLInputElement>(null)
  const rateRef = useRef<HTMLInputElement>(null)
  const tenureRef = useRef<HTMLInputElement>(null)

  function onSubmit(event: FormEvent) {
    event.preventDefault()
    const result = validateInputs(inputs)
    if (!result.ok) {
      dispatch({ type: 'invalid', errors: result.errors })
      // Spec §8.3: focus the first invalid field in order amount → rate → tenure.
      const refs = { amount: amountRef, rate: rateRef, tenure: tenureRef }
      const first = FIELD_ORDER.find((f) => result.errors[f])
      if (first) refs[first].current?.focus()
      return
    }
    const loan = calculateLoan(result.value)
    dispatch({ type: 'calculated', loan })
    // Spec §9.3: save only after a successful calculation. A failed save makes saved
    // calculations unavailable for the rest of the visit.
    if (state.history.available) {
      const saved = saveEntry(createEntry(loan, settings.currency))
      dispatch(
        saved.ok
          ? { type: 'historyChanged', entries: saved.entries }
          : { type: 'historyUnavailable' },
      )
    }
  }

  function onReset() {
    dispatch({ type: 'reset' })
    amountRef.current?.focus()
  }

  const edit = (field: 'amount' | 'rate' | 'tenure') => (value: string) =>
    dispatch({ type: 'edit', field, value })

  return (
    <form className="card form-card" noValidate onSubmit={onSubmit}>
      <CurrencySelect />
      <TextField
        id="amount"
        label={copy.field.amount(settings.currency)}
        value={inputs.amount}
        error={errors.amount}
        inputMode="decimal"
        inputRef={amountRef}
        onChange={edit('amount')}
      />
      <TextField
        id="rate"
        label={copy.field.rate}
        value={inputs.rate}
        error={errors.rate}
        inputMode="decimal"
        inputRef={rateRef}
        onChange={edit('rate')}
      />
      <div className="tenure-row">
        <TextField
          id="tenure"
          label={copy.field.tenure}
          value={inputs.tenure}
          error={errors.tenure}
          inputMode="numeric"
          inputRef={tenureRef}
          onChange={edit('tenure')}
        />
        <div className="field">
          <label htmlFor="unit">{copy.field.unit}</label>
          <select
            id="unit"
            value={inputs.unit}
            onChange={(e) => dispatch({ type: 'setUnit', unit: e.target.value as Unit })}
          >
            {UNITS.map((u) => (
              <option key={u} value={u}>
                {copy.field.unitOptions[u]}
              </option>
            ))}
          </select>
        </div>
      </div>
      <div className="actions">
        <button type="submit" className="primary">
          {copy.btn.calculate}
        </button>
        <button type="button" className="secondary" onClick={onReset}>
          {copy.btn.reset}
        </button>
      </div>
    </form>
  )
}

